// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

contract InvMutTest is Test {
    SimpleWallet c;
    function setUp() public { c = new SimpleWallet(); }
    function testFuzz_property(address nonOwner, uint256 amount) public {
        vm.assume(nonOwner != address(this));
        amount = bound(amount, 1, address(c).balance + 1e18);

        vm.deal(address(c), 10 ether);

        bool ok;
        vm.prank(nonOwner);
        try c.sendMoney(address(0xdead), amount) {
            ok = true;
        } catch {
            ok = false;
        }
        assertFalse(ok);
    }
}
